test('invoiceTotals total formula: subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
    voucher: { code: 'X', amount: 50 },
  };
  const totals = invoiceTotals(invoice);
  const expected = 1000 - 100 + 189 - 50;
  assert.equal(totals.total, expected);
});

// Bulk discount tests (qty >= 10 gets 2.5% extra discount)

test('lineDiscount with 10 units gets bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000 };
  // subtotal: 10000, primary discount: 0, bulk discount: 250
  assert.equal(lineDiscount(line), 250);
});

test('lineDiscount with 9 units does NOT get bulk discount', () => {
  const line = { qty: 9, unitPrice: 1000 };
  // subtotal: 9000, primary discount: 0, bulk discount: 0
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount with 11 units gets bulk discount', () => {
  const line = { qty: 11, unitPrice: 1000 };
  // subtotal: 11000, primary discount: 0, bulk discount: 275
  assert.equal(lineDiscount(line), 275);
});

test('lineDiscount bulk discount applied after primary discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  // subtotal: 10000, primary discount: 1000, remaining: 9000, bulk: 225
  assert.equal(lineDiscount(line), 1225);
});

test('lineDiscount with primary discount and bulk discount', () => {
  const line = { qty: 10, unitPrice: 2000, discountPercent: 5 };
  // subtotal: 20000, primary: 1000, remaining: 19000, bulk: 475
  assert.equal(lineDiscount(line), 1475);
});

test('lineDiscount bulk discount is 2.5% of remainder', () => {
  const line = { qty: 10, unitPrice: 100 };
  // subtotal: 1000, primary: 0, bulk: 25
  assert.equal(lineDiscount(line), 25);
});

test('lineDiscount with 100 units', () => {
  const line = { qty: 100, unitPrice: 100 };
  // subtotal: 10000, primary: 0, bulk: 250
  assert.equal(lineDiscount(line), 250);
});

test('lineDiscount with 10 units and high primary discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 50 };
  // subtotal: 10000, primary: 5000, remaining: 5000, bulk: 125
  assert.equal(lineDiscount(line), 5125);
});

test('lineDiscount with 10 units and 100% primary discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 100 };
  // subtotal: 10000, primary: 10000, remaining: 0, bulk: 0
  assert.equal(lineDiscount(line), 10000);
});

test('lineVat after bulk discount with 10 units', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  // subtotal: 10000, discount (bulk): 250, after discount: 9750, vat: 2047.5 -> 2048
  assert.equal(lineVat(line), 2048);
});

test('lineVat after primary and bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // subtotal: 10000, primary: 1000, bulk: 225, total discount: 1225
  // after discount: 8775, vat: 1842.75 -> 1843
  assert.equal(lineVat(line), 1843);
});

test('lineVat with 9 units (no bulk discount)', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  // subtotal: 9000, discount: 0, vat: 1890
  assert.equal(lineVat(line), 1890);
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000, discount: 250, vat: 2048
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
});

test('invoiceTotals with bulk and primary discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000, primary: 1000, bulk: 225, total discount: 1225
  // vat: 1843
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10000 - 1225 + 1843);
});

test('invoiceTotals with mixed quantities', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line1: 10000, discount: 250, vat: 2048
  // line2: 5000, discount: 0, vat: 1050
  // total subtotal: 15000, total discount: 250, total vat: 3098
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 3098);
});

test('invoiceTotals with three lines including bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 15, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line1: 10000, discount: 250, vat: 2048
  // line2: 9000, discount: 0, vat: 1890
  // line3: 15000, primary: 750, bulk: 356, total discount: 1106, vat: 2946
  // total: subtotal 34000, discount: 1606, vat: 6884
  assert.equal(totals.subtotal, 34000);
  assert.equal(totals.discount, 1606);
});

test('bulk discount with tier discount', () => {
  // This tests that bulk discount works with the tier discount that gets applied in createInvoice
  const line = { qty: 10, unitPrice: 1000, discountPercent: 2.5 };
  // subtotal: 10000, primary: 250, bulk: 244 (2.5% of 9750)
  assert.equal(lineDiscount(line), 494);
});

test('bulk discount boundary at exactly 10 units', () => {
  const line10 = { qty: 10, unitPrice: 1000 };
  const line9 = { qty: 9, unitPrice: 1000 };
  assert.equal(lineDiscount(line10), 250);
  assert.equal(lineDiscount(line9), 0);
});

test('bulk discount with fractional unit price', () => {
  const line = { qty: 10, unitPrice: 333 };
  // subtotal: 3330, bulk: 83 (2.5% of 3330)
  assert.equal(lineDiscount(line), 83);
});

test('bulk discount with large quantity', () => {
  const line = { qty: 1000, unitPrice: 100 };
  // subtotal: 100000, bulk: 2500
  assert.equal(lineDiscount(line), 2500);
});

test('bulk discount returns integer cents', () => {
  const line = { qty: 10, unitPrice: 333, discountPercent: 7.5 };
  const discount = lineDiscount(line);
  assert.ok(Number.isInteger(discount));
});

test('invoiceTotals total with bulk discount formula', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const expected = 10000 - 250 + 2048;
  assert.equal(totals.total, expected);
});

test('bulk discount with voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
    voucher: { code: 'BULK', amount: 100 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000, discount: 250, vat: 2048, voucher: 100
  // total: 10000 - 250 + 2048 - 100
  assert.equal(totals.total, 11698);
});

test('bulk discount on multiple lines with same rate', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 500, vatRate: 21 },
      { qty: 10, unitPrice: 500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // each line: 5000, discount: 125, vat: 1023
  // total: 10000, discount: 250, vat: 2046
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2046);
});

